mapper.select:
SELECT id, product_name, product_code, price
FROM stock_data
WHERE id = #{id}

mapper.update:
UPDATE stock_data
product_code = #{r.productCode}, product_name = #{r.productName}, specification = #{r.specification}, category = #{r.category}, supplier = #{r.supplier}, applicant = #{r.applicant}, approver = #{r.approver}, system_assign = #{r.systemAssign}, updated_by = #{r.updatedBy},
WHERE id = #{id}

mapper.select:
SELECT COALESCE(SUM(CASE WHEN in_quantity > 0 THEN in_quantity ELSE 0 END), 0)
     - COALESCE(SUM(CASE WHEN out_quantity > 0 THEN out_quantity ELSE 0 END), 0)
FROM ${table}
WHERE deleted_at IS NULL
  AND code_number = #{productCode}
